import math

def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def sigma(n):
    if n == 1:
        return 1
    factors = get_prime_factorization(n)
    sum_of_divisors = 1
    for p, e in factors.items():
        # Formula for sum of divisors: (p^(e+1) - 1) / (p - 1)
        term = (p**(e+1) - 1) // (p - 1)
        sum_of_divisors *= term
    return sum_of_divisors

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

print("--- Checking m = 22 through m = 31 ---")
results = {}
for m in range(22, 32):
    s = sigma(m)
    is_sq = is_square(s)
    results[m] = (s, is_sq)
    print(f"m={m}: sigma(m) = {s}, Is Square? {is_sq}")

